from itertools import combinations, product


def _routes(data, exact, minimum_duration):
    required = data.get("required", [])
    bits = {node: 1 << i for i, node in enumerate(required)}
    full = (1 << len(required)) - 1
    source = data["source"]
    start = data["start"]
    coupons = data["coupons"]
    initial_mask = bits.get(source, 0)
    graph = [[] for _ in range(data["n"])]
    for edge in data["edges"]:
        graph[edge["u"]].append(edge)

    initial = (source, initial_mask, 0)
    distances = {initial: start}
    queue = [(start, source, initial_mask, 0)]
    while queue:
        time, node, mask, used = heapq.heappop(queue)
        state = (node, mask, used)
        if distances.get(state) != time:
            continue
        if (node == data["target"] and mask == full
                and (not exact or used == coupons)):
            return {"arrival": time}
        for edge in graph[node]:
            depart = max(time, edge["open"])
            if depart >= edge["close"]:
                continue
            options = [(edge["duration"], used)]
            if used < coupons:
                shortened = max(minimum_duration,
                                edge["duration"] - edge.get("discount", 0))
                options.append((shortened, used + 1))
            next_mask = mask | bits.get(edge["v"], 0)
            for duration, next_used in options:
                arrival = depart + duration
                if arrival > data["deadline"]:
                    continue
                next_state = (edge["v"], next_mask, next_used)
                if arrival < distances.get(next_state, float("inf")):
                    distances[next_state] = arrival
                    heapq.heappush(queue, (arrival, edge["v"], next_mask, next_used))
    return {"arrival": None}


def _ledger(data):
    cutoff = data.get("cutoff", 10**9)
    winners = {}
    for position, event in enumerate(data["events"]):
        if event.get("sequence", 0) > cutoff:
            continue
        event_id = event.get("id", "anonymous:" + str(position))
        key = (event.get("revision", 0), position)
        if event_id not in winners or key > winners[event_id][0]:
            winners[event_id] = (key, event)

    balances = dict(data.get("opening", {}))
    mode = data["rounding"]

    def rounded(numerator):
        if mode == "half_up":
            return (numerator + 5000) // 10000
        return numerator // 10000

    for _, event in winners.values():
        if event.get("void", False):
            continue
        raw = event["price"] * event.get("quantity", 1)
        discount = min(10000, max(0, event.get("discount_bp", 0)))
        net = rounded(raw * (10000 - discount))
        tax = rounded(raw * event.get("tax_bp", 0))
        amount = net + tax
        if event.get("kind") == "refund":
            amount = -amount
        key = event.get("account", "default") + "|" + event.get("currency", "USD")
        balances[key] = balances.get(key, 0) + amount
    return {"balances": balances}


def _resolver(data):
    packages = data["packages"]
    names = sorted(packages, reverse=True)
    features = set(data.get("features", []))
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    choices = [[None] + [row["version"] for row in packages[name]]
               for name in names]
    best_vector = None
    best = None

    for values in product(*choices):
        selected = {name: version for name, version in zip(names, values)
                    if version is not None}
        if any(version in blocked.get(name, []) for name, version in selected.items()):
            continue
        if any(name in pins and pins[name] != version
               for name, version in selected.items()):
            continue

        rows = {name: next(row for row in packages[name]
                           if row["version"] == version)
                for name, version in selected.items()}
        graph = {name: [] for name in selected}
        valid = True
        for name, row in rows.items():
            for dep in row.get("deps", []):
                feature = dep.get("feature", "")
                if feature and feature not in features:
                    continue
                child = dep["name"]
                version = selected.get(child)
                if (version is None or not dep["min"] <= version <= dep["max"]):
                    valid = False
                    break
                graph[name].append(child)
            if not valid:
                break
        if not valid:
            continue

        for name, (low, high) in data["roots"].items():
            version = selected.get(name)
            if version is None or not low <= version <= high:
                valid = False
                break
        if not valid:
            continue

        reachable = set()
        stack = list(data["roots"])
        while stack:
            name = stack.pop()
            if name in reachable:
                continue
            reachable.add(name)
            stack.extend(graph[name])
        if reachable != set(selected):
            continue

        active, finished = set(), set()
        def visit(name):
            if name in active:
                return False
            if name in finished:
                return True
            active.add(name)
            for child in graph[name]:
                if not visit(child):
                    return False
            active.remove(name)
            finished.add(name)
            return True

        if not all(visit(name) for name in graph):
            continue
        vector = tuple(selected.get(name, -1) for name in names)
        if best_vector is None or vector < best_vector:
            best_vector, best = vector, selected

    if best is None:
        return {"error": "unsatisfiable"}
    return {"versions": best}


def _schedule(data):
    jobs = [job for job in data["jobs"]
            if job["id"] not in data.get("blocked", [])]
    k = data["k"]
    mandatory = set(data.get("mandatory", []))
    if len(mandatory) > k or not mandatory.issubset({job["id"] for job in jobs}):
        return {"error": "impossible"}

    quotas = data.get("quotas", {})
    best_value = None
    best_ids = None
    for group in combinations(jobs, k):
        ids = [job["id"] for job in group]
        if not mandatory.issubset(ids):
            continue
        counts = {}
        for job in group:
            counts[job["group"]] = counts.get(job["group"], 0) + 1
        if any(not low <= counts.get(name, 0) <= high
               for name, (low, high) in quotas.items()):
            continue
        intervals = sorted((job["start"], job["end"]) for job in group)
        if any(intervals[i][0] < intervals[i - 1][1]
               for i in range(1, len(intervals))):
            continue
        value = sum(job["value"] for job in group)
        sorted_ids = sorted(ids)
        if (best_value is None or value > best_value
                or (value == best_value and sorted_ids < best_ids)):
            best_value, best_ids = value, sorted_ids

    if best_value is None:
        return {"error": "impossible"}
    return {"selected": best_ids, "value": best_value}


